package com.aoo.bcg.admin;import java.sql.*;import java.time.*;import java.util.*;import org.junit.jupiter.api.*;import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;import static org.junit.jupiter.api.Assertions.*;
class AdminRbacIntegrationTest{@Test void everyButtonHasDistinctFailClosedPermission(){var c=new AdminPermissionCatalog();assertEquals(22,c.routes().size());assertEquals(22,c.routes().stream().map(AdminPermissionCatalog.Route::button).distinct().count());for(var r:c.routes()){String path=r.pattern().replace("{scope}","516").replace("{id}","item-1");assertEquals(r.permission(),c.required(r.method(),path));assertNotNull(r.targetType());assertNotNull(r.risk());assertEquals("control.denied",c.required("DELETE",path));}String rollback="/api/v2/admin/game-profile-releases/516/release-1/rollback";assertEquals("game-profile.rollback",c.required("POST",rollback));assertEquals(AdminAccessPolicy.Risk.HIGH,c.route("POST",rollback).orElseThrow().risk());assertEquals("sensitive-export.download",c.required("GET","/api/v2/admin/sensitive-exports/export-1/download"));assertEquals("map.location.read",c.required("GET","/api/v2/admin/map/ip-location"));assertEquals("control.denied",c.required("POST","/api/v2/admin/game-profiles/516/publish"));assertEquals("control.denied",c.required("POST","/api/v2/admin/game-investigations/9"));}
 @Test @EnabledIfEnvironmentVariable(named="AOO_DB_IT_URL",matches=".+")void roleAndDirectGrantAuthorizeWhileDenialIsAudited()throws Exception{String url=System.getenv("AOO_DB_IT_URL"),user=System.getenv("AOO_DB_IT_USER"),password=System.getenv("AOO_DB_IT_PASSWORD");JdbcAdminResourceRepository.ConnectionFactory f=()->DriverManager.getConnection(url,user,password);long operator=System.currentTimeMillis();String role="it_"+operator;try(var c=f.open();var s=c.createStatement()){s.executeUpdate("INSERT INTO admin_role(role_code,display_name,enabled,created_at) VALUES('"+role+"','IT',1,CURRENT_TIMESTAMP(3))");s.executeUpdate("INSERT INTO admin_role_permission(role_code,permission_code,granted_at) VALUES('"+role+"','appeal.resolve',CURRENT_TIMESTAMP(3))");s.executeUpdate("INSERT INTO admin_operator_role(operator_id,role_code,enabled,granted_by,granted_at) VALUES("+operator+",'"+role+"',1,"+operator+",CURRENT_TIMESTAMP(3))");}var auth=new JdbcAdminAuthorizationService(f);assertTrue(auth.allowed(operator,"appeal.resolve"));assertFalse(auth.allowed(operator,"lifecycle.update"));var audit=new JdbcAdminAuthorizationAudit(f);audit.record("it-"+operator,operator,"lifecycle.update","PUT","/api/v2/admin/data-lifecycle/x",false,Instant.now());try(var c=f.open();var q=c.prepareStatement("SELECT decision FROM admin_authorization_audit WHERE request_id=?")){q.setString(1,"it-"+operator);try(var r=q.executeQuery()){assertTrue(r.next());assertEquals("DENIED",r.getString(1));}}try(var c=f.open();var s=c.createStatement()){s.executeUpdate("DELETE FROM admin_authorization_audit WHERE operator_id="+operator);s.executeUpdate("DELETE FROM admin_operator_role WHERE operator_id="+operator);s.executeUpdate("DELETE FROM admin_role_permission WHERE role_code='"+role+"'");s.executeUpdate("DELETE FROM admin_role WHERE role_code='"+role+"'");}}
}
